// Generates src/data/sequences.ts â€” the frame manifest for the two
// scroll-driven films (bottle / pouring). Re-run after swapping frames:
//
//   npm run sequences
//
import { readdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const GROUPS = [
  { dir: 'public/sequences/bottle', name: 'bottleSequence', id: 'bottle' },
  { dir: 'public/sequences/pouring', name: 'pourSequence', id: 'pouring' },
]

let out =
  '// AUTO-GENERATED by scripts/generate-sequences.mjs â€” do not edit by hand.\n' +
  '// One entry per film frame, in playback order.\n\n'

for (const g of GROUPS) {
  const files = readdirSync(join(process.cwd(), g.dir))
    .filter((f) => /\.(jpe?g|png|webp)$/i.test(f))
    .sort()
  if (files.length === 0) {
    console.error(`no frames found in ${g.dir}`)
    process.exit(1)
  }
  const base = g.dir.replace(/^public/, '')
  out += `/** ${files.length}-frame film â€” ${g.id}. */\n`
  out += `export const ${g.name}: string[] = [\n`
  out += files.map((f) => `  '${base}/${f}',`).join('\n')
  out += '\n]\n\n'
  console.log(`${g.name}: ${files.length} frames`)
}

writeFileSync(join(process.cwd(), 'src/data/sequences.ts'), out)
console.log('wrote src/data/sequences.ts')
